-- Keep Mr. Fluent database metadata/content aligned with the published A2-C2 static student course files.
-- Updates existing rows in place by level code, unit number and lesson sort order; lesson IDs/progress are preserved.
-- No videos are fabricated. Existing video_url values are left untouched.
BEGIN;
WITH seed(level_code,unit_number,unit_title,unit_description) AS (VALUES
('A2',1,'Everyday plans & experiences','Talk about routines, current activities, past events and future arrangements.'),
('A2',2,'People, places & experiences','Describe people and places, compare options, and talk about life experiences.'),
('A2',3,'Communication & problem-solving','Make polite requests, explain problems and give advice.'),
('A2',4,'Stories & practical writing','Tell a short story, connect ideas and write clear everyday messages.'),
('B1',1,'Narratives & turning points','Narrate events with detail and make stories easier to follow.'),
('B1',2,'Opinions & discussion','State a position, support it and respond constructively.'),
('B1',3,'Work, study & society','Communicate about goals, change, responsibilities and public issues.'),
('B1',4,'Fluency & practical communication','Handle misunderstandings, make recommendations and write coherent texts.'),
('B2',1,'Nuance, emphasis & complex time','Use advanced tense choices and phrasing to communicate precise meaning.'),
('B2',2,'Arguments & persuasion','Evaluate claims, qualify opinions and respond to counterarguments.'),
('B2',3,'Professional & academic English','Present complex information and handle formal communication.'),
('B2',4,'Style, idiom & synthesis','Interpret idiomatic language and synthesise information across sources.'),
('C1',1,'Precision, nuance & stance','Express subtle degrees of certainty, evaluation and emphasis.'),
('C1',2,'Critical thinking & argumentation','Interrogate assumptions and construct qualified, well-supported arguments.'),
('C1',3,'Academic & professional discourse','Write concise, structured and appropriately formal material.'),
('C1',4,'Pragmatics, style & synthesis','Interpret implied meaning and combine perspectives with precision.'),
('C2',1,'Lexical precision & subtle meaning','Distinguish near-synonyms and control shades of meaning.'),
('C2',2,'Rhetoric, implication & interpretation','Read between the lines and shape arguments with deliberate rhetorical control.'),
('C2',3,'Register, style & discourse architecture','Shift style deliberately and organise complex material for maximum clarity.'),
('C2',4,'Synthesis, mediation & expert communication','Integrate complex sources and mediate disagreements with precision.')
)
UPDATE public.mrfluent_english_units u
SET title=s.unit_title,description=s.unit_description,is_published=true,updated_at=now()
FROM seed s JOIN public.mrfluent_english_levels l ON l.code=s.level_code
WHERE u.level_id=l.id AND u.unit_number=s.unit_number;

WITH seed(level_code,unit_number,sort_order,title,goal,explain,vocab,examples,questions) AS (VALUES
('A2',1,1,'Present simple vs. present continuous','Choose between routines and actions happening now.','Choose between routines and actions happening now. Focus on meaning, form, register and context. Notice how the examples model this skill: I usually walk to school, but today I am taking the bus.','[["usually","عادةً"],["currently","حاليًا"],["routine","روتين"],["temporary","مؤقت"],["at the moment","في الوقت الحالي"]]'::jsonb,'["I usually walk to school, but today I am taking the bus.","In context: usually — عادةً.","Use the target naturally: I usually walk to school, but today I am taking the bus."]'::jsonb,'[["Look! She ___ a message now.",["writes","is writing","write"],1],["What does “usually” mean in Arabic?",["عادةً","حاليًا","روتين"],0],["Choose the sentence that best matches this lesson: Present simple vs. present continuous.",["I usually walk to school, but today I am taking the bus.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('A2',1,2,'Past simple: regular and irregular verbs','Describe completed events and ask about the past.','Describe completed events and ask about the past. Focus on meaning, form, register and context. Notice how the examples model this skill: We visited the museum and bought two postcards.','[["visited","زار"],["bought","اشترى"],["yesterday","أمس"],["journey","رحلة"],["last weekend","نهاية الأسبوع الماضي"]]'::jsonb,'["We visited the museum and bought two postcards.","In context: visited — زار.","Use the target naturally: We visited the museum and bought two postcards."]'::jsonb,'[["Yesterday, they ___ the old castle.",["visit","visited","visiting"],1],["What does “visited” mean in Arabic?",["زار","اشترى","أمس"],0],["Choose the sentence that best matches this lesson: Past simple: regular and irregular verbs.",["We visited the museum and bought two postcards.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('A2',1,3,'Future plans: going to and present continuous','Explain intentions and arranged plans.','Explain intentions and arranged plans. Focus on meaning, form, register and context. Notice how the examples model this skill: I am meeting my cousin at six, and we are going to see a film.','[["intention","نية"],["arrangement","ترتيب مسبق"],["book","يحجز"],["appointment","موعد"],["plan ahead","يخطط مسبقًا"]]'::jsonb,'["I am meeting my cousin at six, and we are going to see a film.","In context: intention — نية.","Use the target naturally: I am meeting my cousin at six, and we are going to see a film."]'::jsonb,'[["We have tickets. We ___ a film tonight.",["are going to watch","watched","watching yesterday"],0],["What does “intention” mean in Arabic?",["نية","ترتيب مسبق","يحجز"],0],["Choose the sentence that best matches this lesson: Future plans: going to and present continuous.",["I am meeting my cousin at six, and we are going to see a film.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('A2',2,1,'Comparatives and superlatives','Compare people, places and experiences accurately.','Compare people, places and experiences accurately. Focus on meaning, form, register and context. Notice how the examples model this skill: The train is faster than the bus, but the metro is the most convenient.','[["crowded","مزدحم"],["quiet","هادئ"],["convenient","ملائم"],["the most popular","الأكثر شعبية"],["further","أبعد"]]'::jsonb,'["The train is faster than the bus, but the metro is the most convenient.","In context: crowded — مزدحم.","Use the target naturally: The train is faster than the bus, but the metro is the most convenient."]'::jsonb,'[["This is ___ café in our neighbourhood.",["more quiet","the quietest","quiet than"],1],["What does “crowded” mean in Arabic?",["مزدحم","هادئ","ملائم"],0],["Choose the sentence that best matches this lesson: Comparatives and superlatives.",["The train is faster than the bus, but the metro is the most convenient.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('A2',2,2,'Present perfect: experiences','Ask and answer about experiences using ever, never, just and yet.','Ask and answer about experiences using ever, never, just and yet. Focus on meaning, form, register and context. Notice how the examples model this skill: Have you ever tried kayaking? I have never done it, but I would like to.','[["experience","تجربة"],["ever","من قبل"],["never","أبدًا"],["already","بالفعل"],["yet","حتى الآن"]]'::jsonb,'["Have you ever tried kayaking? I have never done it, but I would like to.","In context: experience — تجربة.","Use the target naturally: Have you ever tried kayaking? I have never done it, but I would like to."]'::jsonb,'[["Have you ___ visited Luxor?",["ever","yesterday","last"],0],["What does “experience” mean in Arabic?",["تجربة","من قبل","أبدًا"],0],["Choose the sentence that best matches this lesson: Present perfect: experiences.",["Have you ever tried kayaking? I have never done it, but I would like to.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('A2',2,3,'Describing people and places','Use relative detail and adjectives to make descriptions clearer.','Use relative detail and adjectives to make descriptions clearer. Focus on meaning, form, register and context. Notice how the examples model this skill: It is a lively neighbourhood that has several cafés and a large park.','[["friendly","ودود"],["reliable","يمكن الاعتماد عليه"],["lively","حيوي"],["located","يقع"],["neighbourhood","حيّ"]]'::jsonb,'["It is a lively neighbourhood that has several cafés and a large park.","In context: friendly — ودود.","Use the target naturally: It is a lively neighbourhood that has several cafés and a large park."]'::jsonb,'[["A person you can depend on is ___.",["reliable","crowded","temporary"],0],["What does “friendly” mean in Arabic?",["ودود","يمكن الاعتماد عليه","حيوي"],0],["Choose the sentence that best matches this lesson: Describing people and places.",["It is a lively neighbourhood that has several cafés and a large park.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('A2',3,1,'Polite requests and offers','Use could, would and can for requests and offers.','Use could, would and can for requests and offers. Focus on meaning, form, register and context. Notice how the examples model this skill: Would you mind speaking a little more slowly? I can help you with that form.','[["Could you…?","هل يمكنك…؟"],["Would you mind…?","هل تمانع…؟"],["offer","يعرض"],["available","متاح"],["assistance","مساعدة"]]'::jsonb,'["Would you mind speaking a little more slowly? I can help you with that form.","In context: Could you…? — هل يمكنك…؟.","Use the target naturally: Would you mind speaking a little more slowly? I can help you with that form."]'::jsonb,'[["Which is the most polite request?",["Move your bag.","Could you move your bag, please?","You move bag."],1],["What does “Could you…?” mean in Arabic?",["هل يمكنك…؟","هل تمانع…؟","يعرض"],0],["Choose the sentence that best matches this lesson: Polite requests and offers.",["Would you mind speaking a little more slowly? I can help you with that form.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('A2',3,2,'Advice with should and have to','Give suggestions and describe obligations.','Give suggestions and describe obligations. Focus on meaning, form, register and context. Notice how the examples model this skill: You should save a copy, and you have to submit the form by Friday.','[["advice","نصيحة"],["obligation","التزام"],["deadline","موعد نهائي"],["should","ينبغي"],["have to","يجب أن"]]'::jsonb,'["You should save a copy, and you have to submit the form by Friday.","In context: advice — نصيحة.","Use the target naturally: You should save a copy, and you have to submit the form by Friday."]'::jsonb,'[["You feel ill. You ___ get some rest.",["should","mustn’t to","are"],0],["What does “advice” mean in Arabic?",["نصيحة","التزام","موعد نهائي"],0],["Choose the sentence that best matches this lesson: Advice with should and have to.",["You should save a copy, and you have to submit the form by Friday.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('A2',3,3,'Travel and getting around','Ask for travel information and handle common travel situations.','Ask for travel information and handle common travel situations. Focus on meaning, form, register and context. Notice how the examples model this skill: Could you tell me which platform the train leaves from?','[["platform","رصيف القطار"],["return ticket","تذكرة ذهاب وعودة"],["departure","مغادرة"],["delay","تأخير"],["connection","رحلة مواصلة"]]'::jsonb,'["Could you tell me which platform the train leaves from?","In context: platform — رصيف القطار.","Use the target naturally: Could you tell me which platform the train leaves from?"]'::jsonb,'[["A train leaving later than planned has a ___.",["delay","discount","receipt"],0],["What does “platform” mean in Arabic?",["رصيف القطار","تذكرة ذهاب وعودة","مغادرة"],0],["Choose the sentence that best matches this lesson: Travel and getting around.",["Could you tell me which platform the train leaves from?","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('A2',4,1,'Past continuous and past simple','Describe a background action interrupted by an event.','Describe a background action interrupted by an event. Focus on meaning, form, register and context. Notice how the examples model this skill: I was waiting for the bus when I noticed my wallet was missing.','[["while","بينما"],["suddenly","فجأة"],["interrupt","يقاطع"],["in the middle of","في منتصف"],["notice","يلاحظ"]]'::jsonb,'["I was waiting for the bus when I noticed my wallet was missing.","In context: while — بينما.","Use the target naturally: I was waiting for the bus when I noticed my wallet was missing."]'::jsonb,'[["I ___ dinner when the phone rang.",["cooked","was cooking","am cooking"],1],["What does “while” mean in Arabic?",["بينما","فجأة","يقاطع"],0],["Choose the sentence that best matches this lesson: Past continuous and past simple.",["I was waiting for the bus when I noticed my wallet was missing.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('A2',4,2,'Linking ideas: because, so, although','Connect reasons, results and contrasts.','Connect reasons, results and contrasts. Focus on meaning, form, register and context. Notice how the examples model this skill: Although it was raining, we continued walking because the route was short.','[["because","لأن"],["therefore","لذلك"],["although","على الرغم من"],["however","ومع ذلك"],["result","نتيجة"]]'::jsonb,'["Although it was raining, we continued walking because the route was short.","In context: because — لأن.","Use the target naturally: Although it was raining, we continued walking because the route was short."]'::jsonb,'[["___ it was late, they finished the task.",["Although","Because of","So that"],0],["What does “because” mean in Arabic?",["لأن","لذلك","على الرغم من"],0],["Choose the sentence that best matches this lesson: Linking ideas: because, so, although.",["Although it was raining, we continued walking because the route was short.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('A2',4,3,'Emails and messages','Write friendly messages with a clear purpose and suitable tone.','Write friendly messages with a clear purpose and suitable tone. Focus on meaning, form, register and context. Notice how the examples model this skill: Hi Maya, could we reschedule our meeting for Thursday? Let me know what works for you.','[["subject line","عنوان الرسالة"],["confirm","يؤكد"],["reschedule","يعيد تحديد الموعد"],["available","متاح"],["look forward to","يتطلع إلى"]]'::jsonb,'["Hi Maya, could we reschedule our meeting for Thursday? Let me know what works for you.","In context: subject line — عنوان الرسالة.","Use the target naturally: Hi Maya, could we reschedule our meeting for Thursday? Let me know what works for you."]'::jsonb,'[["A suitable phrase to end a friendly email is ___.",["Yours faithfully to whom","Speak soon","I demand a reply"],1],["What does “subject line” mean in Arabic?",["عنوان الرسالة","يؤكد","يعيد تحديد الموعد"],0],["Choose the sentence that best matches this lesson: Emails and messages.",["Hi Maya, could we reschedule our meeting for Thursday? Let me know what works for you.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('B1',1,1,'Past perfect in storytelling','Show which of two past events happened first.','Show which of two past events happened first. Focus on meaning, form, register and context. Notice how the examples model this skill: By the time we reached the station, the train had already left.','[["by the time","بحلول الوقت الذي"],["realise","يدرك"],["had already","كان قد فعل بالفعل"],["unexpected","غير متوقع"],["evidence","دليل"]]'::jsonb,'["By the time we reached the station, the train had already left.","In context: by the time — بحلول الوقت الذي.","Use the target naturally: By the time we reached the station, the train had already left."]'::jsonb,'[["By the time I arrived, the meeting ___.",["started","had started","has start"],1],["What does “by the time” mean in Arabic?",["بحلول الوقت الذي","يدرك","كان قد فعل بالفعل"],0],["Choose the sentence that best matches this lesson: Past perfect in storytelling.",["By the time we reached the station, the train had already left.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('B1',1,2,'Used to and would','Describe repeated past habits and states.','Describe repeated past habits and states. Focus on meaning, form, register and context. Notice how the examples model this skill: I used to live near the sea, and we would walk along the beach every evening.','[["used to","اعتاد أن"],["would often","كان غالبًا"],["childhood","طفولة"],["nowadays","في الوقت الحاضر"],["get used to","يعتاد على"]]'::jsonb,'["I used to live near the sea, and we would walk along the beach every evening.","In context: used to — اعتاد أن.","Use the target naturally: I used to live near the sea, and we would walk along the beach every evening."]'::jsonb,'[["She ___ be shy, but now she speaks confidently.",["use to","used to","was use to"],1],["What does “used to” mean in Arabic?",["اعتاد أن","كان غالبًا","طفولة"],0],["Choose the sentence that best matches this lesson: Used to and would.",["I used to live near the sea, and we would walk along the beach every evening.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('B1',1,3,'Narrative linking and emphasis','Sequence a story and highlight important moments.','Sequence a story and highlight important moments. Focus on meaning, form, register and context. Notice how the examples model this skill: Just as we were leaving, the lights went out; eventually, the power returned.','[["eventually","في النهاية"],["meanwhile","في هذه الأثناء"],["as soon as","بمجرد أن"],["in the end","في النهاية"],["what surprised me","ما أدهشني"]]'::jsonb,'["Just as we were leaving, the lights went out; eventually, the power returned.","In context: eventually — في النهاية.","Use the target naturally: Just as we were leaving, the lights went out; eventually, the power returned."]'::jsonb,'[["Which phrase signals the final result?",["Meanwhile","Eventually","At first"],1],["What does “eventually” mean in Arabic?",["في النهاية","في هذه الأثناء","بمجرد أن"],0],["Choose the sentence that best matches this lesson: Narrative linking and emphasis.",["Just as we were leaving, the lights went out; eventually, the power returned.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('B1',2,1,'Opinion language and evidence','Express a view and support it with reasons or examples.','Express a view and support it with reasons or examples. Focus on meaning, form, register and context. Notice how the examples model this skill: In my view, public transport should be improved because it reduces congestion.','[["point of view","وجهة نظر"],["evidence","دليل"],["convincing","مقنع"],["in my view","من وجهة نظري"],["to some extent","إلى حد ما"]]'::jsonb,'["In my view, public transport should be improved because it reduces congestion.","In context: point of view — وجهة نظر.","Use the target naturally: In my view, public transport should be improved because it reduces congestion."]'::jsonb,'[["Which phrase introduces an opinion?",["In my view","As soon as","By the time"],0],["What does “point of view” mean in Arabic?",["وجهة نظر","دليل","مقنع"],0],["Choose the sentence that best matches this lesson: Opinion language and evidence.",["In my view, public transport should be improved because it reduces congestion.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('B1',2,2,'Conditionals: real and unreal','Discuss likely results and hypothetical situations.','Discuss likely results and hypothetical situations. Focus on meaning, form, register and context. Notice how the examples model this skill: If more people cycled, the city would have less traffic.','[["unless","ما لم"],["provided that","بشرط أن"],["outcome","نتيجة"],["hypothetical","افتراضي"],["otherwise","وإلا"]]'::jsonb,'["If more people cycled, the city would have less traffic.","In context: unless — ما لم.","Use the target naturally: If more people cycled, the city would have less traffic."]'::jsonb,'[["If I ___ more time, I would volunteer.",["have","had","will have"],1],["What does “unless” mean in Arabic?",["ما لم","بشرط أن","نتيجة"],0],["Choose the sentence that best matches this lesson: Conditionals: real and unreal.",["If more people cycled, the city would have less traffic.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
('B1',2,3,'Reported speech and questions','Report what someone said without repeating the exact words.','Report what someone said without repeating the exact words. Focus on meaning, form, register and context. Notice how the examples model this skill: Nadia said that she was applying for a new position.','[["report","ينقل"],["claim","يدّعي"],["admit","يعترف"],["whether","ما إذا"],["statement","تصريح"]]'::jsonb,'["Nadia said that she was applying for a new position.","In context: report — ينقل.","Use the target naturally: Nadia said that she was applying for a new position."]'::jsonb,'[["“I am tired,” he said. → He said he ___ tired.",["is","was","will be"],1],["What does “report” mean in Arabic?",["ينقل","يدّعي","يعترف"],0],["Choose the sentence that best matches this lesson: Reported speech and questions.",["Nadia said that she was applying for a new position.","This statement is unrelated to the topic.","The sentence is grammatically incomplete."],0]]'::jsonb),
