UPDATE public.mrfluent_english_lessons le
SET title=s.title,
    description=s.goal,
    is_published=true,
    lesson_type=CASE
      WHEN lower(s.title) ~ '(vocabulary|collocation|lexical|near-synonym|idiom|phrasal verb|word choice|connotation)' THEN 'vocabulary'
      WHEN lower(s.title) ~ '(grammar|tense|passive|clause|sentence building|syntax|word order|present simple|past simple|past perfect|present perfect|future form|comparative|conditional|modal|reported speech|inversion|fronting|hedging|concession|nominalisation|relative clause|compound adjective)' THEN 'grammar'
      WHEN lower(s.title) ~ '(writing|essay|report|email|summary|paragraph|letter|memo|proposal)' THEN 'writing'
      WHEN lower(s.title) ~ '(listening|audio|note-taking)' THEN 'listening'
      WHEN lower(s.title) ~ '(reading|critical reading|narrative|storytelling|source analysis)' THEN 'reading'
      WHEN lower(s.title) ~ '(speaking|discussion|debate|communication|fluency|mediation|presentation|negotiation)' THEN 'speaking'
      ELSE 'lesson'
    END,
    content_text =
      'LEARNING GOAL' || E'\n' || s.goal ||
      E'\n\nEXPLANATION\n' || s.explain ||
      E'\n\nVOCABULARY (English — Arabic)\n' ||
      coalesce((SELECT string_agg((v.value->>0) || ' — ' || (v.value->>1),E'\n' ORDER BY v.ordinality)
                FROM jsonb_array_elements(s.vocab) WITH ORDINALITY v(value,ordinality)),'') ||
      E'\n\nEXAMPLES\n' ||
      coalesce((SELECT string_agg(v.value #>> '{}',E'\n' ORDER BY v.ordinality)
                FROM jsonb_array_elements(s.examples) WITH ORDINALITY v(value,ordinality)),'') ||
      E'\n\nPRACTICE QUESTIONS\n' ||
      coalesce((SELECT string_agg(
        'Q' || q.ordinality::text || '. ' || (q.value->>0) || E'\n' ||
        coalesce((SELECT string_agg(chr((64+opt.ordinality)::integer)::text || '. ' || opt.option_value,E'\n' ORDER BY opt.ordinality)
                  FROM jsonb_array_elements_text(q.value->1) WITH ORDINALITY opt(option_value,ordinality)), ''),
        E'\n\n' ORDER BY q.ordinality)
        FROM jsonb_array_elements(s.questions) WITH ORDINALITY q(value,ordinality)), ''),
    updated_at=now()
FROM seed s
JOIN public.mrfluent_english_units u ON u.unit_number=s.unit_number
JOIN public.mrfluent_english_levels l ON l.id=u.level_id AND l.code=s.level_code
WHERE le.unit_id=u.id AND le.sort_order=s.sort_order;
COMMIT;
